using System;
using System.Collections.Generic;
using UnityEngine;

public class PoisonBolasProjectile : Projectile
{
	private static GameObject prefab;

	public PoisonType poisonType;

	private Entity targetEntity;

	private bool targetHit;

	private Vector3 impactPosition;

	private GameObject spriteObject;

	private PoisonEffect poisonEffect;

	private List<PoisonEffect> poisonEffectList = new List<PoisonEffect>();

	private ChaosQuickStopwatch moveLerpStopwatch = new ChaosQuickStopwatch(0.125f);

	private ChaosQuickStopwatch scaleLerpStopwatch = new ChaosQuickStopwatch(0.25f);

	private ChaosQuickStopwatch resetStopwatch = new ChaosQuickStopwatch(0.75f);

	public Sprite[] bolaSprites;

	public float[] colliderRadii;

	public Transform[] poisonEffectArray;

	public float minRotation = 0.5f;

	public float maxRotation = 3f;

	private int maxSizeReached;

	private float scalePercent;

	private AudioSource spinningAudioSource;

	public bool isEmpowered;

	public bool isUltimate;

	public bool releaseOnStart;

	private bool attackCompleted;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/PoisonBolasProjectile.prefab"));

	public override void Awake()
	{
		base.Awake();
		spriteObject = transform.Find("ProjectileSprite").gameObject;
		poisonEffectArray = new Transform[3];
		poisonEffectArray[0] = transform.Find("PoisonEmitters/PoisonEmitter0");
		poisonEffectArray[1] = transform.Find("PoisonEmitters/PoisonEmitter1");
		poisonEffectArray[2] = transform.Find("PoisonEmitters/PoisonEmitter2");
	}

	public override void Start()
	{
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		scaleLerpStopwatch.IsRunning = true;
		scaleLerpStopwatch.IsPaused = true;
		CreatePoisonEffect(transform.Find("ProjectileSprite"));
		if (releaseOnStart)
		{
			ReleaseBolas();
		}
	}

	private void CreatePoisonEffect(Transform followTrans)
	{
		poisonEffect = UnityEngine.Object.Instantiate(PoisonEffect.Prefab, transform.position, Quaternion.identity, transform).GetComponent<PoisonEffect>();
		poisonEffectList.Add(poisonEffect);
		poisonEffect.followTrans = followTrans;
		poisonEffect.worldSpaceSkulls = true;
		poisonEffect.poisonType = poisonType;
	}

	public override void Update()
	{
		if (targetHit)
		{
			RefreshFlightTime(flyTimeOnly: true);
			if (targetEntity != null && targetEntity.hurtBoxTransform != null)
			{
				transform.position = Vector3.Lerp(impactPosition, targetEntity.hurtBoxTransform.position, moveLerpStopwatch.TimePercentage);
			}
			if (scaleLerpStopwatch.IsRunning)
			{
				scalePercent = scaleLerpStopwatch.TimePercentage;
				if (scalePercent >= 0.6f)
				{
					anim.Play("PoisonBolaSmall", -1, 0f);
				}
				else if (maxSizeReached >= 1 && scalePercent >= 0.3f)
				{
					anim.Play("PoisonBolaMed", -1, 0f);
				}
				else if (maxSizeReached >= 2)
				{
					anim.Play("PoisonBolaLarge", -1, 0f);
				}
			}
			else if (!attackCompleted)
			{
				attackCompleted = true;
				spriteObject.SetActive(value: false);
				attackBox.collider.enabled = false;
				PoolManager.GetPoolItem<LeafEmitter>("FallingLeafBurstEmitter").EmitSingle(10, transform.position, null, null, 0f, null, LeafEmitter.LeafColor.LightGreen);
			}
			if (!resetStopwatch.IsRunning)
			{
				ResetProjectile();
			}
		}
		else
		{
			base.Update();
			rotationsPerSecond = Mathf.Lerp(maxRotation, minRotation, ChaosStopwatch.GetTimePercentage(flyStopwatchID));
			rotationVector.z = rotationsPerSecond * 360f;
			scalePercent = scaleLerpStopwatch.TimePercentage;
			if (isUltimate || (maxSizeReached < 2 && scalePercent >= 0.6f))
			{
				anim.Play("PoisonBolaLarge", -1, 0f);
				maxSizeReached = 2;
			}
			else if (maxSizeReached < 1 && scalePercent >= 0.3f)
			{
				anim.Play("PoisonBolaMed", -1, 0f);
				maxSizeReached = 1;
			}
			else if (maxSizeReached == 0)
			{
				anim.Play("PoisonBolaSmall", -1, 0f);
			}
			PlayAudio();
		}
	}

	public void ReleaseBolas()
	{
		CreatePoisonEffect(poisonEffectArray[0]);
		CreatePoisonEffect(poisonEffectArray[1]);
		CreatePoisonEffect(poisonEffectArray[2]);
		scaleLerpStopwatch.IsPaused = false;
		attackBox.collider.enabled = true;
		goThroughWalls = false;
		if (isEmpowered)
		{
			rotationsPerSecond *= 1.5f;
			moveSpeed *= 1.25f;
			flyTime *= 0.5f;
		}
		if (isUltimate)
		{
			flyTime *= 2f;
		}
		RefreshFlightTime();
	}

	public override void RefreshFlightTime(bool flyTimeOnly = false)
	{
		if (!forcedReturn)
		{
			if (!flyTimeOnly)
			{
				scaleLerpStopwatch.Refresh();
			}
			base.RefreshFlightTime(flyTimeOnly);
		}
	}

	private void SetTransformScale(float givenValue)
	{
		transform.localScale = Vector3.one * givenValue;
	}

	private void OnTargetHit(Entity hitEntity)
	{
		if (isUltimate && hitEntity != null && !(hitEntity is Destructible))
		{
			CreatePoisonBomb(hitEntity.transform.position);
		}
		if (!targetHit && (!isEmpowered || !(hitEntity != null)))
		{
			targetHit = true;
			targetEntity = hitEntity;
			if (hitEntity != null)
			{
				rigidbody2D.velocity = Vector2.zero;
				updateVelocity = false;
			}
			moveLerpStopwatch.IsRunning = true;
			resetStopwatch.IsRunning = true;
			scaleLerpStopwatch.IsRunning = true;
			impactPosition = transform.position;
			wallCollider.gameObject.SetActive(value: false);
			DisablePoisonEffects();
		}
	}

	private void CreatePoisonBomb(Vector2 givenPosition)
	{
		PoisonBomb poisonBomb = Globals.ChaosInst<PoisonBomb>(PoisonBomb.Prefab, null, givenPosition);
		poisonBomb.attackBox.SetAttackInfo(attackBox.atkInfo.skillCategory, "PoisonBurst", 5);
		poisonBomb.targetPosition = givenPosition;
		poisonBomb.randomOffset = 0f;
		poisonBomb.explosionDelay = 0f;
		poisonBomb.poisonDuration = 10f;
		poisonBomb.attackRadius = 1.5f;
		poisonBomb.useCastingCircle = false;
		poisonBomb.poisonType = PoisonType.Green;
		poisonBomb.baseFlightTime = 0f;
	}

	private void DisablePoisonEffects()
	{
		foreach (PoisonEffect poisonEffect in poisonEffectList)
		{
			poisonEffect.Disable();
		}
		poisonEffectList.Clear();
	}

	public override void HandleWallCollision(Collider2D other)
	{
		base.HandleWallCollision(other);
		rigidbody2D.velocity = Vector2.zero;
		updateVelocity = false;
	}

	public override void ResetProjectile()
	{
