	public class UseFireBlastState : SkillState
	{
		public new static string staticID = "UseFireBlast";

		private FireBlast currentFB;

		private int ultStopwatchID;

		private AudioSource odLoopAudio;

		public override string OnEnterAnimStr => parent.PBAoEAnimStr;

		public UseFireBlastState(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			isMeleeSkill = true;
			startCooldownOnEnter = false;
			useSmartCD = true;
			SetAnimTimes(0.1f, 0.6f, 0.2f, 0.8f, 0.9f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			GameObject prefab = FireBlast.Prefab;
			Quaternion? givenQuaternion = Globals.GetRotationQuaternion(inputVector);
			currentFB = ChaosInst<FireBlast>(prefab, null, givenQuaternion);
			currentFB.attack.SetAttackInfo(parent.skillCategory, skillID, isUltimate ? 3 : ((!IsEmpowered) ? 1 : 2), isUltimate);
			currentFB.attack.knockbackOverwriteVector = inputVector;
			if (isUltimate)
			{
				currentFB.CircleBlast();
				ultStopwatchID = ChaosStopwatch.Begin(1.05f);
				parent.hud.castBar.StartCast(ultStopwatchID, givenStatus: false);
				ApplyStopElement();
				PlayAudio();
			}
			else
			{
				currentFB.Blast();
				StartCooldownTimer();
			}
			CameraController.ShakeCamera(0.25f);
		}

		public override void ConcludeSkill()
		{
			if (isUltimate && !ChaosStopwatch.Check(ultStopwatchID))
			{
				if (!CancelToDash() && !(currentFB == null))
				{
					PlayAudio();
					currentFB.transform.position = parent.attackOriginTrans.position;
					inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
					parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animHoldTime);
					if (!(inputVector == Vector2.zero))
					{
						currentFB.attack.knockbackOverwriteVector = inputVector;
						currentFB.transform.localEulerAngles = Globals.GetRotationVector(inputVector);
					}
				}
			}
			else
			{
				StartCooldownTimer();
				StopAudio();
				ExitToSkillOrRunOrIdle();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.hud.castBar.EndCast();
			if (currentFB != null)
			{
				currentFB.EndAllAttacks();
			}
			StopAudio();
		}

		private void PlayAudio()
		{
			odLoopAudio = SoundManager.PlayIfNotPlaying("FireBlastODLoop", odLoopAudio, parent.transform);
		}

		private void StopAudio()
		{
			if (odLoopAudio != null)
			{
				odLoopAudio.Stop();
				odLoopAudio = null;
				SoundManager.PlayAudioWithDistance("FireBlastODEnd", parent.transform.position);
			}
		}
	}

