using UnityEngine;
public class ShockBomb : MonoBehaviour
{
	private static GameObject prefab;
	private static int strikeCount = 5;
	private static float burstRadius = 2.25f;
	private float curBurstRadius = burstRadius;
	private ParticleEffect currentLF;
	private ParticleSystemOverride lfOverride;
	private int delayStopwatchID;
	private float delayTime = 0.625f;
	private float lerpValue;
	private float lerpThreshold = 0.1f;
	private string skillCat = string.Empty;
	private string skillID = string.Empty;
	private bool playAudio;
	private bool destroyQueued;
	private Vector2 currentPosition;
	public bool useCastingCircle;
	private CastingCircle currentCC;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ShockBomb.prefab"));
	public void Init(string givenCat, string givenID, bool givenAudio, float givenDelayTime = 0.625f, float radiusOverride = 0f)
	{
		skillCat = givenCat;
		skillID = givenID;
		playAudio = givenAudio;
		delayTime = givenDelayTime;
		if (radiusOverride > 0f)
		{
			curBurstRadius = radiusOverride;
		}
		else
		{
			curBurstRadius = burstRadius;
		}
	}
	private void Start()
	{
		currentPosition = transform.position;
		currentLF = PoolManager.GetPoolItem<ParticleEffect>("LightningField");
		currentLF.Play(10f, currentPosition);
		lfOverride = new ParticleSystemOverride
		{
			simulationSpace = ParticleSystemSimulationSpace.Local,
			radius = 0.25f
		};
		delayStopwatchID = ChaosStopwatch.Begin(delayTime);
		if (useCastingCircle)
		{
			string animName = "Draw";
			Vector3 spawnPos = currentPosition;
			bool disableWithParentVal = false;
			float unitSizeX = curBurstRadius - 0.25f;
			Color? color = CastingCircle.enemyColor;
			float drawTime = delayTime;
			currentCC = CastingCirclePool.Spawn(animName, spawnPos, disableWithParentVal, null, trackParentVal: true, useCastTimeVal: false, 0f, unitSizeX, 0f, color, drawTime);
		}
	}
	private void Update()
	{
		if (destroyQueued)
		{
			return;
		}
		lerpValue = ChaosStopwatch.GetTimePercentage(delayStopwatchID);
		if (lerpValue >= 1f)
		{
			destroyQueued = true;
			LightningBurst.CreateBurst(currentPosition, skillCat, skillID, 1, curBurstRadius);
			CameraController.ShakeCamera(0.25f);
			if (playAudio)
			{
				SoundManager.PlayWithDistAndSPR("ThunderClap", currentPosition);
			}
			ResetObjs();
			if (gameObject != null)
			{
				Object.Destroy(gameObject);
			}
		}
		else if (lerpValue > lerpThreshold)
		{
			lerpThreshold += 0.1f;
			lfOverride.radius = Mathf.Lerp(0f, curBurstRadius, lerpValue);
			if (currentLF != null)
			{
				currentLF.Emit(3, currentPosition, lfOverride);
			}
			if (playAudio)
			{
				SoundManager.PlayWithDistAndSPR("SparkLoopShort", currentPosition);
			}
		}
	}
	private void ResetObjs()
	{
		if (currentLF != null)
		{
			currentLF.Stop();
			currentLF = null;
		}
		if (currentCC != null)
		{
			currentCC.Reset();
			currentCC = null;
		}
	}
	private void OnDestroy()
	{
		ResetObjs();
	}
}
